select k.key,count(*) as predictions_with_key from public.official_predictions p join public.official_races o using(race_date,track,race_no) cross join lateral jsonb_object_keys(case when jsonb_typeof(p.payload->'audit')='object' then p.payload->'audit' else '{}'::jsonb end) as k(key) where o.circuit='JRA' and p.status='FROZEN' and o.race_date between '2026-10-17' and '2026-11-15' group by k.key order by k.key limit 60;
